<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller;use App\Models\User;use App\Services\PostAudience;use App\Services\SocialPolicy;use App\Services\NotificationService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
final class StatusCommentController extends Controller {
 private function actor(Request $r):int {foreach(['actor_id','author_id','user_id','parent_id','reply_to','attachment','attachments','media','media_id'] as $k)abort_if($r->exists($k),422,'unsupported comment field');return (int)$r->user()->id;}
 private function readable(object $c,int $viewer):bool {return $c->state==='ACTIVE'&&User::whereKey($c->author_id)->where('disabled',false)->where('account_status','active')->where('moderation_status','normal')->lockForUpdate()->exists()&&app(SocialPolicy::class)->pairAllowed($viewer,(int)$c->author_id);}
 private function shape(object $c,int $viewer,int $owner):array {$active=$this->readable($c,$viewer);return ['id'=>$c->id,'state'=>$active?'ACTIVE':'UNAVAILABLE','revision'=>(int)$c->revision,'author_id'=>$active?(int)$c->author_id:null,'body'=>$active?$c->body:null,'can_delete'=>$active&&in_array($viewer,[(int)$c->author_id,$owner],true),'can_report'=>$active&&(int)$c->author_id!==$viewer,'created_at'=>$c->created_at];}
 public function index(Request $r,int $postId,PostAudience $policy){$actor=$this->actor($r);$cursor=max(0,(int)$r->query('cursor',0));$ids=DB::table('status_post_comments')->where('status_post_id',$postId)->orderBy('created_at')->orderBy('id')->skip($cursor)->take(20)->get(['id','author_id']);$users=$ids->pluck('author_id')->map(fn($v)=>(int)$v)->unique()->all();return $policy->run($actor,$postId,function($p)use($actor,$cursor,$ids){$comments=DB::table('status_post_comments')->where('status_post_id',$p->id)->whereIn('id',$ids->pluck('id'))->orderBy('created_at')->orderBy('id')->lockForUpdate()->get();$items=[];foreach($comments as $c){$candidate=$ids->firstWhere('id',$c->id);if(!$candidate||(int)$c->author_id!==(int)$candidate->author_id)continue;$items[]=$this->shape($c,$actor,(int)$p->author_user_id);}$count=DB::table('status_post_comments')->where('status_post_id',$p->id)->count();$next=$cursor+$ids->count();return response()->json(['items'=>$items,'meta'=>['next_cursor'=>$next<$count?(string)$next:null,'has_more'=>$next<$count]]);},$users);}
 public function show(Request $r,int $postId,string $commentId,PostAudience $policy){$actor=$this->actor($r);$candidate=DB::table('status_post_comments')->where('id',$commentId)->where('status_post_id',$postId)->first(['author_id']);abort_unless($candidate,404,'unavailable');return $policy->run($actor,$postId,function($p)use($actor,$commentId,$candidate){$c=DB::table('status_post_comments')->where('id',$commentId)->where('status_post_id',$p->id)->lockForUpdate()->first();abort_unless($c&&(int)$c->author_id===(int)$candidate->author_id,404,'unavailable');return response()->json($this->shape($c,$actor,(int)$p->author_user_id));},[(int)$candidate->author_id]);}
 public function store(Request $r,int $postId,PostAudience $policy){$actor=$this->actor($r);$d=$r->validate(['body'=>'required|string|max:280','idempotency_key'=>'required|string|max:80']);$body=trim($d['body']);abort_if($body===''||preg_match('/https?:|www\.|@|\d{5,}|微信|手机号|身份证|wechat/i',$body),422,'comments do not support links or contact details');return $policy->run($actor,$postId,function($p)use($actor,$d,$body){$old=DB::table('status_post_comments')->where('author_id',$actor)->where('idempotency_key',$d['idempotency_key'])->lockForUpdate()->first();if($old){abort_unless((int)$old->status_post_id===(int)$p->id&&$old->body===$body&&$old->state==='ACTIVE',409,'idempotency conflict');return response()->json($this->shape($old,$actor,(int)$p->author_user_id));}abort_if(DB::table('status_post_comments')->where('author_id',$actor)->where('created_at','>',now()->subMinutes(10))->count()>=5,429,'comment limit');$id=(string)Str::uuid();DB::table('status_post_comments')->insert(['id'=>$id,'status_post_id'=>$p->id,'author_id'=>$actor,'body'=>$body,'state'=>'ACTIVE','revision'=>1,'idempotency_key'=>$d['idempotency_key'],'created_at'=>now(),'updated_at'=>now()]);if((int)$p->author_user_id!==$actor)app(NotificationService::class)->createForUser((int)$p->author_user_id,'status_comment','好友动态有新互动','请在当前权限允许时查看',['status_post_id'=>$p->id,'status_comment_id'=>$id,'actor_user_id'=>$actor]);return response()->json($this->shape(DB::table('status_post_comments')->find($id),$actor,(int)$p->author_user_id),201);});}
 public function destroy(Request $r,int $postId,string $commentId,PostAudience $policy){$actor=$this->actor($r);$revision=$r->validate(['revision'=>'required|integer|min:1'])['revision'];$c=DB::table('status_post_comments')->where('id',$commentId)->where('status_post_id',$postId)->first(['author_id']);abort_unless($c,404,'unavailable');return $policy->run($actor,$postId,function($p)use($actor,$commentId,$revision,$c){$row=DB::table('status_post_comments')->where('id',$commentId)->where('status_post_id',$p->id)->lockForUpdate()->first();abort_unless($row&&(int)$row->author_id===(int)$c->author_id&&in_array($actor,[(int)$row->author_id,(int)$p->author_user_id],true),404,'unavailable');abort_unless($row->state==='ACTIVE'&&(int)$row->revision===$revision,409,'stale comment');DB::table('status_post_comments')->where('id',$commentId)->update(['state'=>'DELETED','revision'=>$revision+1,'updated_at'=>now()]);return response()->json(['id'=>$commentId,'state'=>'DELETED','revision'=>$revision+1,'body'=>null]);},[(int)$c->author_id]);}
 public function report(Request $r,int $postId,string $commentId,PostAudience $policy){$actor=$this->actor($r);$d=$r->validate(['reason_code'=>'required|string|max:64','detail'=>'nullable|string|max:1000']);$c=DB::table('status_post_comments')->where('id',$commentId)->where('status_post_id',$postId)->first(['author_id']);abort_unless($c,404,'unavailable');return $policy->run($actor,$postId,function($p)use($actor,$commentId,$c,$d){$row=DB::table('status_post_comments')->where('id',$commentId)->where('status_post_id',$p->id)->lockForUpdate()->first();abort_unless($row&&(int)$row->author_id===(int)$c->author_id&&$this->readable($row,$actor)&&(int)$row->author_id!==$actor,404,'unavailable');$old=DB::table('moderation_reports')->where('reporter_id',$actor)->where('target_status_comment_id',$commentId)->where('status','new')->first();$id=$old?->id??DB::table('moderation_reports')->insertGetId(['reporter_id'=>$actor,'target_user_id'=>$row->author_id,'target_status_post_id'=>$p->id,'target_status_comment_id'=>$commentId,'category'=>'status_comment','reason_code'=>$d['reason_code'],'detail'=>$d['detail']??null,'status'=>'new','appeal_status'=>'none','created_at'=>now(),'updated_at'=>now()]);return response()->json(['id'=>$id,'status'=>'new']);},[(int)$c->author_id]);}
}
